def add_task():
    """Add a new task to the to-do list."""
    task = input("Enter a task to add to the to-do list (or type 'quit' to exit): ")

    if task.lower() == "quit":
        print("Goodbye!")
        return

    task_list.append(task)
    print(f"To-Do List:")
    print((f"{len(task_list)+1}. {task}\n"))

def display_list():
    """Display the current to-do list."""
    if not task_list:
        print("To-Do List is empty.")
        return

    print(f"To-Do List:")
    for i, task in enumerate(task_list):
        print((f"{i+1}. {task}\n"))

task_list = []

while True:
    print("\n1. Add Task\n2. Display List\n3. Quit\n")
    choice = input("Enter your choice: ")

    if choice == "1":
        add_task()
    elif choice == "2":
        display_list()
    elif choice == "3":
        break
    else:
        print("Invalid choice. Please try again.")
